import { signal, computed, effect } from '@pyreon/reactivity'

export function Cart(props: { price: number }) {
  const qty = signal(1)
  const total = computed(() => props.price * qty())

  effect(() => {
    document.title = `Total: ${total()}`
  })

  return (
    <button onClick={() => qty.update((n) => n + 1)}>
      {qty()} × {props.price} = {total()}
    </button>
  )
}

