import { signal, effect, createSelector } from '@pyreon/reactivity'

const selected = signal(-1)
const isSelected = createSelector(() => selected())

let runs = 0
for (let id = 0; id < 10_000; id++) {
  effect(() => {
    isSelected(id) // in a real row: class={isSelected(id) ? 'row on' : 'row'}
    runs++
  })
}

runs = 0
selected.set(42)
selected.set(7)
console.log(runs) // 3: one row for the first pick, then two for the move

import { signal, createResource } from '@pyreon/reactivity'

const query = signal('')
const results = createResource(
  () => query(),
  (q) => fetch(`/api/search?q=${encodeURIComponent(q)}`).then((r) => r.json()),
)

query.set('p')  // slow request
